const fs = require('fs');
const path = require('path');

const topicsPath = path.resolve('config/post_topics.json');
const draftsPath = path.resolve('data/pending_drafts.json');

let topics = [];
if (fs.existsSync(topicsPath)) {
  try {
    topics = JSON.parse(fs.readFileSync(topicsPath, 'utf8'));
  } catch (err) {
    topics = [];
  }
}

if (!Array.isArray(topics) || topics.length === 0) {
  topics = [
    {
      id: 1,
      slug: 'database-sharding-vs-partitioning',
      title: 'Database Sharding vs Partitioning',
      concept: 'Horizontal scaling and partition keys in high scale systems',
      keywords: ['Database', 'Sharding', 'Partitioning'],
      language: 'ar',
      status: 'pending'
    }
  ];
}

// Pick next unposted topic
let selectedTopic = topics.find((t) => t.status === 'pending') || topics[0];

// Load existing drafts to calculate sequential Draft ID
let drafts = [];
if (fs.existsSync(draftsPath)) {
  try {
    drafts = JSON.parse(fs.readFileSync(draftsPath, 'utf8'));
    if (!Array.isArray(drafts)) drafts = [];
  } catch (err) {
    drafts = [];
  }
}

const maxId = drafts.reduce((max, d) => Math.max(max, Number(d.id) || 0), 0);
const nextDraftId = maxId + 1;

return [
  {
    json: {
      draftId: nextDraftId,
      topic: selectedTopic,
      topicsPath,
      draftsPath
    }
  }
];

const fs = require('fs');
const path = require('path');

const input = $input.first().json;
const topic = input.topic || {};
const draftId = input.draftId || 1;
const slug = topic.slug || 'draft_' + draftId;

// 1. Dual-visual asset check: local assets/<slug>.* first
const assetsDir = path.resolve('assets');
let imagePath = null;
const candidateExtensions = ['.png', '.jpg', '.jpeg', '.svg', '.webp'];

if (fs.existsSync(assetsDir)) {
  for (const ext of candidateExtensions) {
    const filePath = path.join(assetsDir, `${slug}${ext}`);
    if (fs.existsSync(filePath)) {
      imagePath = filePath;
      break;
    }
  }
}

// Fallback to generated image directory
if (!imagePath) {
  const generatedDir = path.resolve('data/generated_images');
  if (!fs.existsSync(generatedDir)) {
    fs.mkdirSync(generatedDir, { recursive: true });
  }
  imagePath = path.join(generatedDir, `${slug}.png`);
  if (!fs.existsSync(imagePath)) {
    fs.writeFileSync(imagePath, '');
  }
}

// 2. Technical post generation adhering to 5 elements
const isArabic = topic.language !== 'en';
let postText = '';

if (isArabic) {
  postText = `💡 معضلة معمارية: ${topic.title || 'تصميم الأنظمة الموزعة'}\n\n` +
    `عند التوسع في الأنظمة ذات الحمولات العالية، يواجه الفريق الهندسي معضلة: ${topic.concept || 'تحقيق التوازن بين زمن الاستجابة والاتساق'}.\n\n` +
    `🔍 التفاصيل الهندسية والـ Mechanics:\n` +
    `• تقسيم الخدمات وتقليل الـ Network Latency.\n` +
    `• معالجة حالات الـ Failover لضمان High Availability.\n` +
    `• اعتماد Observability شاملة لعزل عنق الزجاجة (Bottlenecks).\n\n` +
    `📌 أهم التوصيات البرمجية:\n` +
    `1. اتخذ القرارات المعمارية بناءً على قياسات حقيقية وليس التخمين.\n` +
    `2. تجنب الـ Over-engineering قبل أن يتطلب الـ Scale ذلك فعلياً.\n\n` +
    `💬 سؤال للمهندسين: كيف تتعاملون مع هذا التحدي في أنظمتكم الإنتاجية؟\n\n` +
    `#SystemDesign #Backend #SoftwareEngineering #Architecture #CleanCode`;
} else {
  postText = `💡 Architectural Dilemma: ${topic.title || 'Distributed Systems Design'}\n\n` +
    `When scaling distributed architectures under high concurrency, engineers encounter the challenge of: ${topic.concept || 'balancing throughput and strong consistency'}.\n\n` +
    `🔍 Technical Deep-Dive & Mechanics:\n` +
    `• Service decoupling and reducing cross-boundary network latency.\n` +
    `• Resilient failover handling to safeguard High Availability.\n` +
    `• Comprehensive observability and distributed tracing for root-cause isolation.\n\n` +
    `📌 Key Engineering Takeaways:\n` +
    `1. Drive architectural choices by measured profiling rather than conjecture.\n` +
    `2. Resist premature over-engineering until real bottlenecks emerge.\n\n` +
    `💬 Question for engineering leaders: How do you address this tradeoff in your production stacks?\n\n` +
    `#SystemDesign #Backend #SoftwareEngineering #Architecture #CleanCode`;
}

// 3. Persist new pending draft to data/pending_drafts.json
const draftsPath = input.draftsPath || path.resolve('data/pending_drafts.json');
let drafts = [];
if (fs.existsSync(draftsPath)) {
  try {
    drafts = JSON.parse(fs.readFileSync(draftsPath, 'utf8'));
    if (!Array.isArray(drafts)) drafts = [];
  } catch (err) {
    drafts = [];
  }
}

const newDraft = {
  id: draftId,
  topic: topic.slug || topic.title,
  text: postText,
  post_text: postText,
  image_path: imagePath,
  status: 'pending',
  created_at: new Date().toISOString()
};

drafts.push(newDraft);
const draftsDir = path.dirname(draftsPath);
if (!fs.existsSync(draftsDir)) {
  fs.mkdirSync(draftsDir, { recursive: true });
}
fs.writeFileSync(draftsPath, JSON.stringify(drafts, null, 2), 'utf8');

const formattedCaption = `[Draft ID: #${draftId}]\n\n${postText}\n\n─── Action Instructions ───\n• Approve: /approve ${draftId}\n• Reject: /reject ${draftId}`;

return [
  {
    json: {
      id: draftId,
      text: postText,
      post_text: postText,
      image_path: imagePath,
      caption: formattedCaption
    }
  }
];
